import { unstable_cache } from 'next/cache';
import { getAllProducts as fetchAllProducts } from './db';

// Define the shape of the data returned by getAllProducts
interface ProductsData {
  timestamp: string;
  products: { id: number; name: string; price: number }[];
}

// Wrap the fetch function with unstable_cache
export const getCachedProducts = unstable_cache(
  async () => {
    return (await fetchAllProducts()) as ProductsData;
  },
  ['products-cache-key'], // Cache key
  { tags: ['products'] } // Tags for invalidation
);

export declare function getAllProducts(): Promise<{
  timestamp: string;
  products: { id: number; name: string; price: number }[];
}>;

import { Suspense } from 'react';
import { getCachedProducts } from '@/lib/products';
import { revalidateTag } from 'next/cache';

async function ProductList() {
  const { products, timestamp } = await getCachedProducts();

  return (
    <div className="space-y-4">
      <div className="text-sm text-gray-500">
        Last updated: {new Date(timestamp).toLocaleString()}
      </div>
      <div className="grid gap-4">
        {products.map((product) => (
          <div key={product.id} className="p-4 border rounded shadow-sm">
            <h3 className="font-semibold">{product.name}</h3>
            <p className="text-gray-600">${product.price}</p>
          </div>
        ))}
      </div>
    </div>
  );
}

export default async function Page() {
  async function syncCatalog() {
    'use server';
    revalidateTag('products');
  }

  return (
    <div className="p-8 max-w-4xl mx-auto">
      <div className="flex justify-between items-center mb-6">
        <h1 className="text-2xl font-bold">Product Catalog</h1>
        <form action={syncCatalog}>
          <button 
            type="submit"
            className="px-4 py-2 bg-blue-600 text-white rounded hover:bg-blue-700 transition-colors"
          >
            Sync latest catalog
          </button>
        </form>
      </div>

      <Suspense fallback={<div className="text-gray-500">Loading products...</div>}>
        <ProductList />
      </Suspense>
    </div>
  );
}

